3→/**
4→ * Утилиты для расчета оптимального хода в крестиках-ноликах
5→ * Чистый минимакс — гарантирует ничью минимум
6→ */
7→object TicTacToeUtils {
8→
9→    /**
10→     * Находит лучший ход для игрока O (наш ход)
11→     */
12→    fun getBestMove(board: Array<CharArray>): BoardIndex {
13→        var bestScore = Int.MIN_VALUE
14→        var bestMove = BoardIndex(1, 1)
15→
16→        for (row in 0..2) {
17→            for (col in 0..2) {
18→                if (board[row][col] == '\u0000') {
19→                    board[row][col] = 'O'
20→                    val score = minimax(board, depth = 0, isMaximizing = false)
21→                    board[row][col] = '\u0000'
22→                    if (score > bestScore) {
23→                        bestScore = score
24→                        bestMove = BoardIndex(row, col)
25→                    }
26→                }
27→            }
28→        }
29→        return bestMove
30→    }
31→
32→    /**
33→     * Минимакс без эвристик — идеальная игра
34→     */
35→    private fun minimax(board: Array<CharArray>, depth: Int, isMaximizing: Boolean): Int {
36→        val winner = getWinner(board)
37→        if (winner == 'O') return 10 - depth  // быстрая победа лучше
38→        if (winner == 'X') return depth - 10  // медленное поражение лучше
39→        if (isBoardFull(board)) return 0       // ничья
40→
41→        if (isMaximizing) {
42→            var best = Int.MIN_VALUE
43→            for (r in 0..2) {
44→                for (c in 0..2) {
45→                    if (board[r][c] == '\u0000') {
46→                        board[r][c] = 'O'
47→                        best = maxOf(best, minimax(board, depth + 1, false))
48→                        board[r][c] = '\u0000'
49→                    }
50→                }
51→            }
52→            return best
53→        } else {
54→            var best = Int.MAX_VALUE
55→            for (r in 0..2) {
56→                for (c in 0..2) {
57→                    if (board[r][c] == '\u0000') {
58→                        board[r][c] = 'X'
59→                        best = minOf(best, minimax(board, depth + 1, true))
60→                        board[r][c] = '\u0000'
61→                    }
62→                }
63→            }
64→            return best
65→        }
66→    }
67→
68→    /**
69→     * Возвращает победителя ('O', 'X') или null
70→     */
71→    private fun getWinner(board: Array<CharArray>): Char? {
72→        // Строки
73→        for (r in 0..2) {
74→            if (board[r][0] != '\u0000' && board[r][0] == board[r][1] && board[r][1] == board[r][2])
75→                return board[r][0]
76→        }
77→        // Столбцы
78→        for (c in 0..2) {
79→            if (board[0][c] != '\u0000' && board[0][c] == board[1][c] && board[1][c] == board[2][c])
80→                return board[0][c]
81→        }
82→        // Диагонали
83→        if (board[0][0] != '\u0000' && board[0][0] == board[1][1] && board[1][1] == board[2][2])
84→            return board[0][0]
85→        if (board[0][2] != '\u0000' && board[0][2] == board[1][1] && board[1][1] == board[2][0])
86→            return board[0][2]
87→        return null
88→    }
89→
90→    private fun isBoardFull(board: Array<CharArray>): Boolean {
91→        return board.all { row -> row.all { it != '\u0000' } }
92→    }
